<div class="modal" x-show="cuentaActual && !cobro && !devolucion && !comprobante" role="dialog" aria-modal="true" aria-labelledby="table-account-title">
<div class="card dialog operation-dialog table-account-dialog">
    <header class="account-heading"><div><p>Detalle de la cuenta</p><h2 id="table-account-title" x-text="cuentaActual ? (/^mesa\b/i.test(cuentaActual.mesa) ? cuentaActual.mesa : 'Mesa '+cuentaActual.mesa) : ''"></h2></div><button type="button" @click="cuentaActual=null" :disabled="busy">Cerrar</button></header>
    <section class="account-summary" aria-label="Resumen de la cuenta"><div class="account-outstanding"><span x-text="Number(cuentaActual?.pendiente)>0?'Pendiente de pago':'Cuenta pagada'"></span><strong x-text="money(cuentaActual?.pendiente)"></strong></div><dl><div><dt>Total consumido</dt><dd x-text="money(cuentaActual?.total)"></dd></div><div><dt>Pagado</dt><dd x-text="money(cuentaActual?.pagado)"></dd></div></dl></section>
    <section class="account-consumption"><h3>Consumos</h3>
    <p class="muted" x-show="!cuentaActual?.pedidos?.length">Esta mesa aún no tiene consumos.</p>
    <template x-for="p in cuentaActual?.pedidos||[]" :key="p.id"><article class="account-order" :data-status="p.estado"><header><strong x-text="'Pedido #'+p.id"></strong><span class="pill" :data-status="p.estado" x-text="nombreEstado(p.estado)"></span></header>
        <ul class="account-lines"><template x-for="d in p.detalles" :key="d.id"><li><span class="account-quantity" x-text="d.cantidad+' ×'"></span><span x-text="d.nombre_producto"></span><strong x-text="money(d.subtotal)"></strong></li></template></ul>
        <p class="account-notes" x-show="p.notas" x-text="p.notas"></p>
        <button type="button" class="primary table-delivery" x-show="p.estado==='listo' && user?.permisos.pedidos" @click="entregarPedidoMesa(p)" :disabled="busy||cargando" x-text="t('registrar_entrega')"></button>
        <details class="account-order-options" x-show="user?.permisos.devoluciones || user?.rol==='dueno'"><summary>Gestión del pedido</summary><div><button @click="comprobante=p" :disabled="busy">Ver constancia</button><button x-show="user?.permisos.caja && Number(p.saldo_pendiente)>0 && p.estado!=='cancelado'" @click="prepararCobro(p)" :disabled="busy||!caja">Registrar pago de este pedido</button><button x-show="user?.permisos.devoluciones && Number(p.pagado)>Number(p.devuelto) && p.estado!=='cancelado'" @click="prepararDevolucion(p)" :disabled="busy||!caja">Devolver o anular</button></div></details>
    </article></template>
    <nav class="account-pagination" x-show="cuentaActual?.ultima_pagina>1" aria-label="Páginas de consumos"><button @click="verCuenta(cuentaActual.id,cuentaActual.pagina-1)" :disabled="busy||cuentaActual?.pagina<=1">Anterior</button><span x-text="cuentaActual?.pagina+' / '+cuentaActual?.ultima_pagina"></span><button @click="verCuenta(cuentaActual.id,cuentaActual.pagina+1)" :disabled="busy||cuentaActual?.pagina>=cuentaActual?.ultima_pagina">Siguiente</button></nav>
    </section>
    <section class="account-payment-choice" x-show="cuentaActual?.abierta && Number(cuentaActual?.pendiente)>0" aria-labelledby="account-payment-title">
        <h3 id="account-payment-title">Forma de pago</h3><p>Consulta al cliente cómo desea pagar.</p>
        <label>Medio de pago<select x-model="medioCuenta" :disabled="busy"><option value="efectivo">Efectivo</option><option value="yape">Yape directo</option><option value="plin">Plin directo</option><option value="tarjeta">Tarjeta en POS</option></select></label>
        <p class="payment-instruction" x-show="medioCuenta==='efectivo'">El personal autorizado recibe el efectivo, registra el importe y entrega el vuelto.</p>
        <p class="payment-instruction" x-show="['yape','plin'].includes(medioCuenta)">Verifica la recepción en la cuenta del restaurante antes de registrar el pago. Una captura del cliente no confirma el ingreso.</p>
        <p class="payment-instruction" x-show="medioCuenta==='tarjeta'">Procesa el pago en el terminal del restaurante y verifica su aprobación antes de registrarlo.</p>
        <p class="payment-availability">Pago online por pasarela: todavía no disponible.</p>
    </section>
    <footer class="account-footer">
        <p class="account-payment-note" x-show="Number(cuentaActual?.pendiente)>0 && !user?.permisos.caja && !(user?.permisos.cobrar_efectivo && medioCuenta==='efectivo')">Indica el medio elegido al cajero. Esta selección no envía una solicitud ni confirma el pago.</p>
        <p class="account-payment-note" x-show="Number(cuentaActual?.pendiente)>0 && user?.permisos.caja && !caja">Abre tu turno de caja para registrar el pago.</p>
        <div class="account-main-actions"><button type="button" class="primary" x-show="cuentaActual?.abierta && Number(cuentaActual?.pendiente)>0 && ((user?.permisos.caja && caja) || (user?.permisos.cobrar_efectivo && medioCuenta==='efectivo'))" @click="cobrarCuenta()" :disabled="busy">Continuar al cobro</button><button type="button" x-show="user?.permisos.caja && !caja && Number(cuentaActual?.pendiente)>0" @click="cuentaActual=null;ir('caja')" :disabled="busy">Ir a Mi caja</button><button x-show="cuentaActual?.abierta && user?.permisos.pedidos" @click="agregarConsumo()" :disabled="busy">Añadir consumo</button><button x-show="puedeLiberarMesa" @click="cerrarCuenta()" :disabled="busy">Liberar mesa</button></div>
        <button type="button" class="account-print-options" @click="imprimirCuenta()" :disabled="busy">Imprimir precuenta</button><p class="payment-availability">La boleta electrónica requiere configurar la emisión SUNAT del restaurante.</p>
        <p class="alert" role="alert" x-show="error" x-text="error"></p>
    </footer>
</div></div>
<template x-if="cancelacion"><div class="modal" role="dialog" aria-modal="true" aria-label="Cancelar pedido"><form class="card dialog" @submit.prevent="cancelarPedido()"><h2>Cancelar pedido</h2><p class="muted">Un plato preparado se registra como merma. La cancelación conserva el historial.</p><label>Motivo<textarea x-model="cancelacion.motivo" minlength="5" maxlength="500" required></textarea></label><label><input type="checkbox" x-model="cancelacion.reponer_stock">Devolver existencias al inventario (solo productos recuperables)</label><p class="alert" x-show="error" x-text="error"></p><button class="primary" :disabled="busy">Confirmar cancelación</button><button type="button" @click="cancelacion=null" :disabled="busy">Volver</button></form></div></template>
<template x-if="devolucion"><div class="modal" role="dialog" aria-modal="true" aria-label="Devolución"><form class="card dialog" @submit.prevent="devolver()"><h2>Registrar devolución</h2><p class="muted">Devuelve el dinero por el medio indicado y registra después la operación. No ejecuta transferencias bancarias.</p><label>Monto<input type="number" min=".01" step=".01" x-model="devolucion.monto" required></label><label>Medio<select x-model="devolucion.medio_pago"><option value="efectivo">Efectivo</option><option value="yape">Yape</option><option value="plin">Plin</option><option value="tarjeta">Tarjeta</option></select></label><label>Motivo<textarea x-model="devolucion.motivo" minlength="5" maxlength="500" required></textarea></label><label><input type="checkbox" x-model="devolucion.anular">Anular la venta completa (requiere devolver todo lo cobrado)</label><label><input type="checkbox" x-model="devolucion.reponer_stock">Reponer productos recuperables al stock</label><p class="alert" x-show="error" x-text="error"></p><button class="primary" :disabled="busy||!caja">Confirmar devolución</button><button type="button" @click="devolucion=null" :disabled="busy">Volver</button></form></div></template>
<div class="modal" x-show="recetaActual" role="dialog" aria-modal="true" aria-label="Receta y presentación"><form class="card dialog operation-dialog" @submit.prevent="guardarReceta()"><h2 x-text="'Receta / presentación: '+recetaActual?.nombre"></h2><p class="muted">Cantidad de unidades base que consume cada venta. Ejemplo: una caja consume 12 botellas. No se admiten recetas anidadas. Vaciar la receta vuelve al stock propio.</p><div class="row"><input aria-label="Buscar insumo" x-model="recetaBusqueda"><button type="button" @click="recetaPagina=1;buscarInsumos()" :disabled="busy">Buscar insumos</button></div><template x-for="p in recetaOpciones" :key="p.id"><div class="row"><span x-text="p.nombre+' · '+p.unidad"></span><button type="button" @click="if(!recetaItems.some(r=>r.insumo_id===p.id))recetaItems.push({insumo_id:p.id,cantidad:1,nombre:p.nombre})">Añadir</button></div></template><div class="row"><button type="button" :disabled="busy||recetaPagina<=1" @click="recetaPagina--;buscarInsumos()">Anterior</button><button type="button" :disabled="busy||recetaPagina>=recetaUltima" @click="recetaPagina++;buscarInsumos()">Siguiente</button></div><template x-for="(r,i) in recetaItems" :key="r.insumo_id"><div class="row"><span x-text="r.nombre"></span><input aria-label="Unidades por venta" type="number" min="1" max="10000" step="1" x-model="r.cantidad" required><button type="button" @click="recetaItems.splice(i,1)">Quitar</button></div></template><p class="alert" x-show="error" x-text="error"></p><button class="primary" :disabled="busy">Guardar composición</button><button type="button" :disabled="busy" @click="recetaActual=null">Volver</button></form></div>
